using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Implementations ---

var notebook = new Notebook();

var searchTool = AIFunctionFactory.Create(
    (string query) =>
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        // Simulated search results keyed by topic keywords
        var results = new List<SearchResult>();

        if (query.Contains("quantum", StringComparison.OrdinalIgnoreCase))
        {
            results.Add(new("MIT Technology Review",
                "Quantum computing uses qubits that can exist in superposition, enabling parallel computation. " +
                "Google's Willow chip (2024) demonstrated quantum error correction below threshold for the first time. " +
                "IBM's Heron processor targets 5,000+ qubits by 2025."));
            results.Add(new("Nature Physics",
                "Key challenges remain: decoherence times are limited to microseconds in superconducting qubits. " +
                "Topological qubits by Microsoft promise inherent error protection. " +
                "Quantum advantage has been shown for specific sampling problems but not general computation."));
            results.Add(new("IEEE Spectrum",
                "Applications include drug discovery (molecular simulation), cryptography (Shor's algorithm threatens RSA), " +
                "optimization (logistics, finance), and machine learning acceleration. " +
                "Post-quantum cryptography standards were finalized by NIST in 2024."));
        }
        else if (query.Contains("artificial intelligence", StringComparison.OrdinalIgnoreCase)
              || query.Contains(" AI ", StringComparison.OrdinalIgnoreCase)
              || query.StartsWith("AI ", StringComparison.OrdinalIgnoreCase))
        {
            results.Add(new("Stanford HAI Report",
                "Large language models have transformed NLP. Multimodal models now handle text, images, and audio. " +
                "Agentic AI systems can plan and execute multi-step tasks autonomously."));
            results.Add(new("Reuters",
                "Global AI investment exceeded $200 billion in 2025. Regulation efforts include the EU AI Act " +
                "and proposed US frameworks. Concerns about job displacement affect 30% of current roles."));
        }
        else if (query.Contains("climate", StringComparison.OrdinalIgnoreCase)
              || query.Contains("renewable", StringComparison.OrdinalIgnoreCase))
        {
            results.Add(new("IPCC 2025 Update",
                "Global temperatures have risen 1.2°C above pre-industrial levels. Renewable energy now provides " +
                "40% of global electricity. Solar costs dropped 90% in the last decade."));
            results.Add(new("Bloomberg NEF",
                "Battery storage capacity tripled in 2024. Electric vehicles represent 25% of new car sales globally. " +
                "Green hydrogen projects are scaling but remain expensive at $4-6/kg."));
        }
        else
        {
            results.Add(new("Wikipedia",
                $"General information about '{query}': This is a broad topic with multiple facets " +
                "spanning scientific, social, and economic dimensions."));
            results.Add(new("Google Scholar",
                $"Academic research on '{query}' shows growing interest with publications " +
                "increasing 15% year-over-year in recent studies."));
        }

        return JsonSerializer.Serialize(results);
    },
    "web_search",
    "Searches the web for information on a given query and returns relevant results.");

var addNoteTool = AIFunctionFactory.Create(
    ([Description("A concise note capturing a key finding")] string note,
     [Description("The source or category for this note")] string source) =>
    {
        notebook.AddNote(note, source);
        Console.WriteLine($"  📝 Note added ({source}): {note[..Math.Min(note.Length, 80)]}...");
        return $"Note saved. Total notes: {notebook.Count}";
    },
    "add_note",
    "Saves a research note with its source for later summarization.");

var getNotesTool = AIFunctionFactory.Create(
    () =>
    {
        var notes = notebook.GetNotes();
        Console.WriteLine($"  📋 Retrieved {notes.Count} notes");
        return JsonSerializer.Serialize(notes);
    },
    "get_notes",
    "Retrieves all saved research notes to review or summarize findings.");

// --- Agent Setup ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "no-key";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient();

var chatOptions = new ChatOptions
{
    Tools = [searchTool, addNoteTool, getNotesTool],
    Temperature = 0.3f
};

// --- Research Loop ---

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬 AI Research Agent           ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or       ║");
Console.WriteLine("║  type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("📌 Research topic: ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System,
            """
            You are a research agent. Given a topic, you must:
            1. Search the web for information (make 2-3 searches with different queries)
            2. Save key findings as notes using the add_note tool
            3. After gathering enough information, retrieve your notes and produce a
               well-structured summary with sections and source attribution.
            Always search before summarizing. Be thorough but concise.
            """),
        new(ChatRole.User, $"Research this topic and provide a summary: {topic}")
    };

    Console.WriteLine($"\n🚀 Researching: {topic}\n");

    // Agent loop: keep going until the model produces a final response with no tool calls
    const int maxIterations = 15;
    for (int i = 0; i < maxIterations; i++)
    {
        ChatResponse response = await client.GetResponseAsync(messages, chatOptions);

        // Append the full response (including any tool-call content) to the conversation
        messages.AddMessages(response);

        // Check if any part of the response is a function call
        var functionCalls = response.Messages
            .SelectMany(m => m.Contents.OfType<FunctionCallContent>())
            .ToList();

        if (functionCalls.Count == 0)
        {
            // No tool calls — the model's text is the final answer
            var answer = response.Messages
                .SelectMany(m => m.Contents.OfType<TextContent>())
                .Select(t => t.Text)
                .FirstOrDefault();

            Console.WriteLine("\n══════════════════ Research Summary ══════════════════\n");
            Console.WriteLine(answer ?? "(No summary generated)");
            Console.WriteLine("\n═════════════════════════════════════════════════════\n");
            break;
        }

        // Execute every tool call and feed results back
        foreach (var fc in functionCalls)
        {
            var result = await fc.InvokeAsync();
            messages.Add(new ChatMessage(ChatRole.Tool, [result]));
        }
    }
}

Console.WriteLine("👋 Goodbye!");

// --- Supporting Types ---

record SearchResult(string Source, string Snippet);

class Notebook
{
    private readonly List<NoteEntry> _notes = [];

    public int Count => _notes.Count;

    public void AddNote(string note, string source) =>
        _notes.Add(new NoteEntry(note, source, DateTime.UtcNow));

    public List<NoteEntry> GetNotes() => [.. _notes];

    public void Clear() => _notes.Clear();
}

record NoteEntry(string Note, string Source, DateTime Timestamp);

